test("req.setBody() with edge cases - request body", function() {
  const data = req.getBody();
  const expected = [
    "empty=",
    "null=",
    "undefined=",
    "zero=0",
    "false=false",
    "=empty_key",
    "key=value1",
    "name=bruno",
    "key=value2"
  ].join("&");

  expect(data).to.eql(expected);
});

